];
const state = { started: false, paused: false, health: 100, maxHealth: 100, focus: 0, level: 1, sparks: 0, relics: 0, bossIndex: 0, bossHealth: 0, bossPhase: 1, bossActive: false, bossIntro: false, bossDefeated: [], attackCooldown: 0, heavyCooldown: 0, dodgeTime: 0, dodgeCooldown: 0, invulnerable: 0, combo: 0, comboTimer: 0, jump: 0, jumpVelocity: 0, cloudTime: 0, cloneTime: 0, immobilizeCooldown: 0, staffLong: false, transformed: false, transformTime: 0, lockOn: false, quality: 'Medium', motion: true, toastTimer: 0, currentZone: 0, lastSave: 0 };
