if (saved) { state.level = saved.level || 1; state.sparks = saved.sparks || 0; state.relics = saved.relics || 0; state.bossIndex = clamp(saved.bossIndex || 0, 0, bossData.length - 1); state.bossDefeated = saved.bossDefeated || []; state.health = state.maxHealth = saved.maxHealth || 100; }

const renderer = new THREE.WebGLRenderer({ canvas: $('game-canvas'), antialias: true, alpha: false, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.65)); renderer.setSize(innerWidth, innerHeight, false); renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFSoftShadowMap; renderer.outputColorSpace = THREE.SRGBColorSpace; renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure = 1.24;
