const fill = new THREE.DirectionalLight(0x8db6bc, 1.1); fill.position.set(13, 9, -19); scene.add(fill);
const world = new THREE.Group(); scene.add(world);
const mat = (color, roughness = .8, metalness = 0) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const mats = {
  earth: mat(0x45473c), moss: mat(0x526047), stone: mat(0x777366), darkStone: mat(0x4b4c46), jade: mat(0x405e4e), bark: mat(0x46382c), bamboo: mat(0x566a48), leaf: mat(0x526b4a), gold: mat(0xd2a84e, .35, .58), red: mat(0x8e302b, .52, .12), robe: mat(0xbca87c), skin: mat(0x9c6144), monkey: mat(0x80553f), black: mat(0x211e20), fire: new THREE.MeshBasicMaterial({ color: 0xffb546 }), glow: new THREE.MeshBasicMaterial({ color: 0xd6ac60, transparent: true, opacity: .24, side: THREE.DoubleSide })
};
const sphereGeo = new THREE.SphereGeometry(1, 16, 12);
function addMesh(parent, geometry, material, pos, scale, rot) { const m = new THREE.Mesh(geometry, material); if (pos) m.position.set(...pos); if (scale) m.scale.set(...scale); if (rot) m.rotation.set(...rot); m.castShadow = true; m.receiveShadow = true; parent.add(m); return m; }
