let dmg=(heavy?38:17)+Math.floor(state.level*2.7)+(state.staffLong?7:0)+(state.transformed?19:0);if(state.jump>0)dmg*=1.24;if(enemy.userData.weakTimer>0)dmg*=1.55;if(source==='clone')dmg*=.48;
if(isBoss){state.bossHealth-=dmg;state.focus=clamp(state.focus+(heavy?13:7),0,100);enemy.userData.stagger=heavy?.42:.22;enemy.userData.weakTimer=Math.max(0,enemy.userData.weakTimer-.1);if(state.bossHealth<=0){defeatBoss(enemy);return true;}const percent=state.bossHealth/bossData[state.bossIndex].hp;if(percent<=.5&&state.bossPhase===1){state.bossPhase=2;enemy.userData.phase=2;$('boss-phase').textContent='II';showMessage('THE DEMON REVEALS ITS TRUE FORM','PHASE II — THE MOUNTAIN ANSWERS');enemy.userData.base.emissive=new THREE.Color(0x5c1d16);enemy.userData.base.emissiveIntensity=.46;enemy.scale.multiplyScalar(1.09);state.bossHealth=Math.min(state.bossHealth+bossData[state.bossIndex].hp*.1,bossData[state.bossIndex].hp*.62);showToast('PHASE II · THE YAOGUAI RAGE DEEPENS');}const pct=100*state.bossHealth/bossData[state.bossIndex].hp;$('boss-fill').style.width=`${pct}%`;$('boss-health-text').textContent=`${Math.ceil(pct)}%`;}
