function cloudSomersault(){if(state.cloudTime>0||!state.started)return;state.cloudTime=3.1;state.invulnerable=.8;state.focus=clamp(state.focus+6,0,100);showToast('CLOUD SOMERSAULT · RIDE THE WIND');}
function cloneTechnique(){if(state.cloneTime>0||state.focus<34||!state.started)return;state.focus-=34;state.cloneTime=7;showToast('CLONE TECHNIQUE · THREE SHADOWS ANSWER');for(let i=0;i<3;i++){const clone=addMesh(scene,new THREE.ConeGeometry(.38,1.45,7),new THREE.MeshBasicMaterial({color:0xc9a96f,transparent:true,opacity:.3}),[hero.root.position.x+random(-2,2),1,hero.root.position.z+random(-2,2)]);clone.userData.life=7;clone.userData.clone=true;fx.push(clone);}}
function transform(){if(state.transformTime>0||!state.started)return;state.transformed=true;state.transformTime=10;state.focus=clamp(state.focus+10,0,100);hero.root.scale.setScalar(1.15);showToast('STONE MONKEY FORM · IRON WILL');effectAt(hero.root.position,0xef8d53,1.4);}
function toggleStaff(){state.staffLong=!state.staffLong;hero.staff.scale.set(1,state.staffLong?1.55:1,1);$('staff-state').style.background=state.staffLong?'#e4bd70':'transparent';showToast(state.staffLong?'GOLDEN STAFF · LONG FORM':'GOLDEN STAFF · RESTING FORM');}
function jump(){if(state.jump>0||!state.started)return;state.jumpVelocity=5.8;state.jump=.01;}
