function updateQuest(){const i=state.bossIndex;if(i>=bossData.length){$('quest-text').textContent='The old road remembers';$('quest-distance').textContent='COMPLETE';return;}if(state.bossActive){$('quest-text').textContent=`Defeat ${bossData[i].name}`;$('quest-distance').textContent='YAOGUAI KING';}else{$('quest-text').textContent=i===0?'Follow the old stone path':`Seek ${bossData[i].name}`;const d=hero.root.position.distanceTo(bossPositions[i]);$('quest-distance').textContent=`${Math.max(0,Math.floor(d))} m`;}}

let renderScale=.9;let cameraYaw=0;let lastFrame=performance.now();let elapsed=0;let shrineReady=false;let soundEnabled=false;let audioContext=null;
function applyQuality(level=state.quality){state.quality=level;const settings={Low:[.65,false,0],Medium:[.82,true,1],High:[1,true,1],Ultra:[1,true,2]}[level]||[.82,true,1];renderScale=Math.min(Number($('scale-slider').value)/100,settings[0]);renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,1.65)*renderScale);renderer.setSize(innerWidth,innerHeight,false);renderer.shadowMap.enabled=settings[1];moon.shadow.mapSize.set(settings[2]===0?512:settings[2]===1?1024:2048,settings[2]===0?512:settings[2]===1?1024:2048);$('quality-select').value=level;}
function startGame(){state.started=true;state.paused=false;$('start-screen').classList.add('hidden');$('menu-screen').classList.add('hidden');$('settings-screen').classList.add('hidden');hero.root.position.y=0;showToast('THE PILGRIMAGE BEGINS');setRegion();updateHud();updateQuest();}
function openOverlay(id){state.paused=true;$(id).classList.remove('hidden');}
function closeOverlays(){for(const id of ['menu-screen','settings-screen'])$(id).classList.add('hidden');state.paused=false;}
function toggleMenu(){if(!state.started)return;if(!$('menu-screen').classList.contains('hidden')){closeOverlays();return;}$('settings-screen').classList.add('hidden');openOverlay('menu-screen');updateHud();}
function openSettings(){if(!$('settings-screen').classList.contains('hidden')){$('settings-screen').classList.add('hidden');state.paused=false;return;}$('menu-screen').classList.add('hidden');openOverlay('settings-screen');}
function interact(){if(!state.started)return;if(hero.root.position.distanceTo(shrine.position)<4){state.health=state.maxHealth;state.focus=100;saveProgress();updateHud();showToast('SHRINE RESTORED · PILGRIMAGE SAVED');return;}showToast('THE OLD ROAD CALLS YOU ONWARD');}
function tryUpgrade(){if(state.sparks<60){showToast('NEED 60 SPARKS TO TEMPER THE STAFF');return;}state.sparks-=60;state.level++;state.maxHealth+=5;state.health=state.maxHealth;saveProgress();updateHud();showToast('STAFF TEMPERED · POWER INCREASED');}
function studySkill(){if(state.relics<1){$('skill-detail').textContent='Recover a yaoguai relic to awaken a new technique.';return;}if(state.sparks<100){$('skill-detail').textContent='A new technique costs 100 sparks. Keep exploring.';return;}state.sparks-=100;state.relics--;state.focus=100;state.level++;saveProgress();updateHud();$('skill-detail').textContent='Technique awakened: spirit returns more readily in battle.';showToast('NEW TECHNIQUE AWAKENED');}
function updateMovement(dt){let x=input.x,z=input.z;if(keys.has('KeyA')||keys.has('ArrowLeft'))x-=1;if(keys.has('KeyD')||keys.has('ArrowRight'))x+=1;if(keys.has('KeyW')||keys.has('ArrowUp'))z-=1;if(keys.has('KeyS')||keys.has('ArrowDown'))z+=1;const v=new THREE.Vector3(x,0,z);if(v.lengthSq()>1)v.normalize();if(v.lengthSq()>.01){const speed=state.cloudTime>0?9:state.transformed?4.7:4.1;hero.root.position.addScaledVector(v,speed*dt);hero.root.rotation.y=Math.atan2(-v.x,-v.z);hero.body.position.y=Math.sin(elapsed*12)*.035;hero.armL.rotation.x=Math.sin(elapsed*12)*.15;hero.legL.rotation.x=Math.sin(elapsed*12)*.24;hero.legR.rotation.x=-hero.legL.rotation.x;}else{hero.body.position.y=lerp(hero.body.position.y,0,Math.min(1,dt*8));hero.armL.rotation.x=lerp(hero.armL.rotation.x,0,Math.min(1,dt*8));hero.legL.rotation.x=lerp(hero.legL.rotation.x,0,Math.min(1,dt*8));hero.legR.rotation.x=lerp(hero.legR.rotation.x,0,Math.min(1,dt*8));}hero.root.position.x=clamp(hero.root.position.x,-27,27);hero.root.position.z=clamp(hero.root.position.z,-169,13);}
function updateCamera(dt){const target=new THREE.Vector3(hero.root.position.x,hero.root.position.y+1.15,hero.root.position.z);if(state.lockOn){const t=findTarget();if(t){const angle=Math.atan2(hero.root.position.x-t.position.x,hero.root.position.z-t.position.z);cameraYaw=lerp(cameraYaw,angle,Math.min(1,dt*2));}}const offset=new THREE.Vector3(Math.sin(cameraYaw)*1.25,4.35,8.5);camera.position.lerp(target.clone().add(offset),Math.min(1,dt*5));camera.lookAt(target.x, target.y+.2, target.z-1.6);}
function updateInteractionHint(){const near=hero.root.position.distanceTo(shrine.position)<4;$('interaction-hint').classList.toggle('visible',near);}
function toggleLock(){state.lockOn=!state.lockOn;$('lock-indicator').classList.toggle('visible',state.lockOn);$('lock-button').classList.toggle('locked',state.lockOn);if(state.lockOn){const t=findTarget();if(t){const d=new THREE.Vector3().subVectors(t.position,hero.root.position);hero.root.rotation.y=Math.atan2(-d.x,-d.z);}}}
function playTone(freq=440,duration=.08){if(!soundEnabled)return;try{audioContext??=new AudioContext();const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.frequency.value=freq;gain.gain.setValueAtTime(.035,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+duration);osc.connect(gain);gain.connect(audioContext.destination);osc.start();osc.stop(audioContext.currentTime+duration);}catch{}}
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.04,(now-lastFrame)/1000);lastFrame=now;elapsed+=dt;if(state.started&&!state.paused){updateMovement(dt);if(!state.bossActive&&state.bossIndex<bossData.length&&!state.bossDefeated.includes(state.bossIndex)&&hero.root.position.distanceTo(bossPositions[state.bossIndex])<8.2)beginBossIntro();updateEnemies(dt,elapsed);updateWorld(dt,elapsed);if(state.bossActive&&state.bossIntro===false&&Math.random()<dt*.035)showToast(bossData[state.bossIndex].weak);if(now-state.lastSave>45000)saveProgress();updateInteractionHint();updateQuest();if(Math.floor(now/150)!==Math.floor((now-dt*1000)/150))drawMinimap();}else if(!state.started){updateWorld(dt,elapsed);}updateCamera(dt);renderer.render(scene,camera);}

window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight,false);});
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;const map={KeyJ:'attack',KeyK:'heavy',Space:'dodge',KeyQ:'immobilize',KeyE:'interact',KeyF:'cloud',KeyR:'clones',KeyT:'transform',KeyG:'staff'};if(map[e.code]){if(map[e.code]==='interact')interact();else action(map[e.code]);}if(e.code==='Escape'||e.code==='Tab'){e.preventDefault();toggleMenu();}if(e.code==='KeyL')toggleLock();});window.addEventListener('keyup',e=>keys.delete(e.code));
document.querySelectorAll('[data-action]').forEach(button=>{button.addEventListener('pointerdown',e=>{e.preventDefault();action(button.dataset.action);});});
const joystick=$('joystick'),knob=$('joy-knob');joystick.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;joystick.setPointerCapture(e.pointerId);});joystick.addEventListener('pointermove',e=>{if(joyPointer!==e.pointerId)return;const r=joystick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),max=r.width*.34,scale=len>max?max/len:1;input.x=dx*scale/max;input.z=dy*scale/max;knob.style.transform=`translate(${dx*scale}px,${dy*scale}px)`;});const resetJoy=()=>{joyPointer=null;input.x=0;input.z=0;knob.style.transform='';};joystick.addEventListener('pointerup',resetJoy);joystick.addEventListener('pointercancel',resetJoy);
$('begin-game').addEventListener('click',startGame);$('menu-open').addEventListener('click',toggleMenu);$('settings-open').addEventListener('click',openSettings);$('resume-button').addEventListener('click',closeOverlays);$('save-button').addEventListener('click',()=>{saveProgress();showToast('PILGRIMAGE SAVED');});$('upgrade-button').addEventListener('click',tryUpgrade);$('skill-button').addEventListener('click',studySkill);$('lock-button').addEventListener('click',toggleLock);$('continue-game').addEventListener('click',()=>{const completed=state.bossIndex>=bossData.length;$('victory-screen').classList.add('hidden');$('victory-screen').classList.remove('victory-active');state.paused=false;if(completed){showMessage('THE PILGRIMAGE IS COMPLETE','THE MOUNTAIN REMEMBERS');return;}setRegion();updateQuest();showToast('THE OLD ROAD OPENS');});$('quality-select').addEventListener('change',e=>applyQuality(e.target.value));$('scale-slider').addEventListener('input',()=>applyQuality(state.quality));$('motion-toggle').addEventListener('change',e=>state.motion=e.target.checked);$('sound-toggle').addEventListener('click',()=>{soundEnabled=!soundEnabled;$('sound-toggle').classList.toggle('active',soundEnabled);showToast(soundEnabled?'SPIRIT TONES ENABLED':'SPIRIT TONES MUTED');});document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',closeOverlays));
$('start-screen').addEventListener('click',e=>{if(e.target===$('start-screen'))startGame();});
$('victory-screen').addEventListener('click',e=>{if(e.target===$('victory-screen'))$('continue-game').click();});
