for(let i=0;i<15;i++){await call('Runtime.evaluate',{expression:"document.querySelector('[data-action=heavy]').dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,cancelable:true,pointerId:1,pointerType:'touch'}))"});await new Promise(r=>setTimeout(r,400));r=await call('Runtime.evaluate',{expression:"JSON.stringify({...__debugState(),hud:document.querySelector('#boss-health-text').textContent,victory:!document.querySelector('#victory-screen').classList.contains('hidden')})",returnByValue:true});console.log(i+1,r.result.result.value);const v=JSON.parse(r.result.result.value);if(v.victory)break;await new Promise(r=>setTimeout(r,750));}
